<div class="uv-dialog-backdrop" x-show="reviewTarget" x-cloak @keydown.escape.window="closeReview()" @click.self="closeReview()" role="dialog" aria-modal="true" aria-label="Write a review">
<section class="uv-dialog" @click.stop x-trap.inert.noscroll="reviewTarget"><button class="uv-dialog-close" type="button" @click="closeReview()" aria-label="Close review dialog">×</button><aside class="uv-dialog-context"><img :src="reviewTarget?.item.imageUrl" :alt="reviewTarget?.item.title"><div><h3 x-text="reviewTarget?.item.title"></h3><p x-text="reviewTarget?.item.variantTitle"></p><p>Order <span x-text="reviewTarget?.order.number"></span></p></div></aside><div class="uv-dialog-main"><h2>Write a review</h2>
<div x-show="reviewSubmitted" class="uv-notice">Review submitted. Your review will be published after approval.</div>
<form x-show="!reviewSubmitted" @submit.prevent="submitReview($event.currentTarget)" data-review-form data-review-endpoint="{{ route('customer.reviews.store') }}" :data-order-item-id="reviewTarget?.item.id" novalidate>
<p class="uv-error" x-show="reviewErrors.rating" x-text="reviewErrors.rating"></p>
<p>Your rating</p><div class="uv-dialog-stars">@for($star=1;$star<=5;$star++)<button type="button" @click="reviewRating={{ $star }};reviewErrors.rating=null" @mouseenter="reviewHoverRating={{ $star }}" @mouseleave="reviewHoverRating=0" :class="(reviewHoverRating||reviewRating)>={{ $star }}?'selected':''" aria-label="{{ $star }} star" x-text="(reviewHoverRating||reviewRating)>={{ $star }}?'★':'☆'">☆</button>@endfor</div><label>Review title *<input x-model="reviewTitle" required placeholder="Give your review a title"><small class="uv-error" x-show="reviewErrors.title" x-text="reviewErrors.title"></small></label><label>Your review *<textarea x-model="reviewText" required rows="4" placeholder="Share your experience"></textarea><small class="uv-error" x-show="reviewErrors.comment" x-text="reviewErrors.comment"></small></label>
<label>Photos (optional)</label><input x-ref="reviewPhotosInput" type="file" accept="image/jpeg,image/png,image/webp" multiple @change="selectReviewPhotos($event)" hidden><div class="uv-dialog-photos"><button class="uv-dialog-upload" type="button" @click="$refs.reviewPhotosInput.click()">Upload photos<small>Up to 5 photos · 5 MB each</small></button><template x-for="(photo,index) in reviewPhotos" :key="photo.url"><div><img :src="photo.url" :alt="photo.file.name"><button type="button" @click="removeReviewPhoto(index)" aria-label="Remove photo">×</button></div></template></div><p class="uv-error" x-show="reviewErrors.photos" x-text="reviewErrors.photos"></p>
<p class="uv-muted">Your review will be published after approval.</p><div class="uv-dialog-actions"><button type="button" class="uv-outline" @click="closeReview()" :disabled="reviewSubmitting">Cancel</button><button type="submit" class="uv-primary" :disabled="reviewSubmitting" x-text="reviewSubmitting?'Submitting…':'Submit for review'">Submit for review</button></div></form></div></section></div>
